    private var planDisplay:String{let name=effectiveQuota<=2_050_000_000 ? language.text("Free","Gratuit"):language.text("Plan","Forfait");return "\(name) · \(bytes(effectiveQuota))"}
    var body: some View { NavigationStack{ScrollView{VStack(alignment:.leading,spacing:16){Text("Libérons").font(.system(size:38,weight:.bold,design:.rounded));Text(language.text("Your memories, without the storage stress.","Vos souvenirs, sans le stress du stockage.")).foregroundStyle(.secondary);VStack(alignment:.leading,spacing:16){Label(language.text("Your photo library","Votre photothèque"),systemImage:"photo.stack.fill").font(.headline);Text(analyzer.formattedSize).font(.system(size:48,weight:.bold,design:.rounded));Text(language.text("across \(total.formatted()) photos and videos","répartis sur \(total.formatted()) photos et vidéos")).foregroundStyle(.secondary);HStack(spacing:10){Metric(icon:"photo.fill",value:analyzer.photoCount.formatted(),label:"Photos",tint:.blue);Metric(icon:"video.fill",value:analyzer.videoCount.formatted(),label:language.text("Videos","Vidéos"),tint:.purple)}}.card();VStack(alignment:.leading,spacing:14){HStack{Label("Libérons",systemImage:"icloud.fill").font(.headline).foregroundStyle(.blue);Spacer();Text(bytes(cloud.protectedBytes)).fontWeight(.bold)};ProgressView(value:min(1,Double(cloud.protectedBytes+cloud.pendingBytes)/Double(effectiveQuota))).tint(.blue);HStack(spacing:10){Metric(icon:"checkmark.shield.fill",value:cloud.protectedCount.formatted(),label:language.text("Protected","Protégés"),tint:.green);Metric(icon:"externaldrive.fill",value:planDisplay,label:language.text("Libérons plan","Forfait Libérons"),tint:.blue)}}.card();HStack(spacing:10){Metric(icon:"shield.checkered",value:"\(percent)%",label:language.text("Library protected","Photothèque protégée"),tint:.green);DeviceMediaMetric(value:total.formatted(),label:language.text("On this iPhone","Sur cet iPhone"))};VStack(alignment:.leading,spacing:12){Text(language.text("Protection status","État de protection")).font(.headline);Label(cloud.protectedCount>0 ? language.text("Libérons protection active","Protection Libérons active"):language.text("Ready to protect","Prêt à protéger"),systemImage:cloud.protectedCount>0 ? "checkmark.circle.fill":"shield.fill").foregroundStyle(cloud.protectedCount>0 ? .green:.orange);Divider();Label(language.text("Originals stay on this iPhone until you choose to free space.","Les originaux restent sur cet iPhone jusqu’à ce que vous choisissiez de libérer de l’espace."),systemImage:"iphone").font(.subheadline).foregroundStyle(.secondary)}.card();Button{guard !refreshing else{return};refreshing=true;Task{async let a:Void=analyzer.refreshDashboardFast();async let b:Void=cloud.refresh();_=await(a,b);refreshing=false}}label:{HStack{if refreshing{ProgressView().controlSize(.small)};Label(language.text(refreshing ? "Refreshing…":"Refresh dashboard",refreshing ? "Actualisation…":"Actualiser le tableau de bord"),systemImage:"arrow.clockwise")}.frame(maxWidth:.infinity).frame(height:42)}.buttonStyle(.borderedProminent).disabled(refreshing||cloud.isLoading)}.padding(20).padding(.bottom,100)}.background(LiberonsTheme.canvas).toolbar(.hidden,for:.navigationBar)} }
    private func bytes(_ n:Int64)->String{n==0 ? language.text("0 KB","0 Ko"):ByteCountFormatter.string(fromByteCount:n,countStyle:.file)}
}

