private struct StoragePlanView: View {
    @ObservedObject var cloud:CloudStorageSummary;@ObservedObject var language:LanguageStore
    private var used:Int64{cloud.protectedBytes+cloud.pendingBytes};private var effectiveQuota:Int64{cloud.quotaBytes>0 ? cloud.quotaBytes:2_000_000_000};private var available:Int64{max(0,effectiveQuota-used)}
    private let plans:[(name:String,bytes:Int64,price:String,detailEN:String,detailFR:String,popular:Bool)]=[("2 GB",2_000_000_000,"Free","Your free Libérons space","Votre espace Libérons gratuit",false),("50 GB",50_000_000_000,"$4.99/month","More room for everyday memories","Plus d’espace pour vos souvenirs du quotidien",false),("100 GB",100_000_000_000,"$7.99/month","For growing photo libraries","Pour les photothèques qui grandissent",false),("250 GB",250_000_000_000,"$12.99/month","A great balance for photos and videos","Un excellent équilibre pour vos photos et vidéos",true),("500 GB",500_000_000_000,"$17.99/month","For large photo and video libraries","Pour les grandes photothèques et vidéothèques",false),("1 TB",1_000_000_000_000,"$24.99/month","For extensive memory collections","Pour les grandes collections de souvenirs",false)]
    var body: some View {ScrollView{VStack(alignment:.leading,spacing:18){VStack(alignment:.leading,spacing:14){HStack{Image(systemName:"icloud.fill").font(.title).foregroundStyle(.blue);VStack(alignment:.leading){Text(language.text("Current plan","Forfait actuel")).font(.caption).foregroundStyle(.secondary);Text(currentPlanName).font(.title2.bold())};Spacer();Text(language.text("CURRENT","ACTUEL")).font(.caption2.bold()).foregroundStyle(.blue).padding(.horizontal,9).padding(.vertical,6).background(Color.blue.opacity(0.10),in:Capsule())};ProgressView(value:min(1,Double(used)/Double(effectiveQuota))).tint(.blue);HStack{VStack(alignment:.leading){Text(language.text("Used","Utilisé")).font(.caption).foregroundStyle(.secondary);Text(used==0 ? language.text("0 KB","0 Ko"):ByteCountFormatter.string(fromByteCount:used,countStyle:.file)).fontWeight(.semibold)};Spacer();VStack(alignment:.trailing){Text(language.text("Available","Disponible")).font(.caption).foregroundStyle(.secondary);Text(ByteCountFormatter.string(fromByteCount:available,countStyle:.file)).fontWeight(.semibold)}}}.card();VStack(alignment:.leading,spacing:12){Text(language.text("Available plans","Forfaits disponibles")).font(.title3.bold());Text(language.text("Monthly Libérons plans.","Forfaits mensuels Libérons.")).font(.subheadline).foregroundStyle(.secondary);ForEach(Array(plans.enumerated()),id:\.offset){index,plan in if index>0{Divider()};HStack(spacing:13){ZStack{RoundedRectangle(cornerRadius:13).fill(isCurrent(plan.bytes) ? Color.blue.opacity(0.12):Color.secondary.opacity(0.08)).frame(width:46,height:46);Image(systemName:plan.bytes>=1_000_000_000_000 ? "externaldrive.fill":"icloud.fill").foregroundStyle(isCurrent(plan.bytes) ? .blue:.secondary)};VStack(alignment:.leading,spacing:4){HStack(spacing:7){Text(plan.name).font(.headline);if plan.popular{Text(language.text("MOST POPULAR","PLUS POPULAIRE")).font(.system(size:9,weight:.bold)).foregroundStyle(.white).padding(.horizontal,7).padding(.vertical,3).background(Color.blue,in:Capsule())};if isCurrent(plan.bytes){Text(language.text("Current","Actuel")).font(.caption2.bold()).foregroundStyle(.blue).padding(.horizontal,7).padding(.vertical,3).background(Color.blue.opacity(0.10),in:Capsule())}};Text(localizedPrice(plan.price)).font(.subheadline.bold()).foregroundStyle(plan.price=="Free" ? .green:.primary);Text(language.text(plan.detailEN,plan.detailFR)).font(.caption).foregroundStyle(.secondary)};Spacer();if isCurrent(plan.bytes){Image(systemName:"checkmark.circle.fill").foregroundStyle(.blue).font(.title3)}}.padding(.vertical,5)}}.card();VStack(alignment:.leading,spacing:12){Label(language.text("Your Libérons protection","Votre protection Libérons"),systemImage:"checkmark.shield.fill").font(.headline).foregroundStyle(.green);HStack{Text(language.text("Protected memories","Souvenirs protégés"));Spacer();Text(cloud.protectedCount.formatted()).fontWeight(.semibold)};if cloud.pendingBytes>0{Divider();HStack{Text(language.text("Being protected","En cours de protection"));Spacer();Text(ByteCountFormatter.string(fromByteCount:cloud.pendingBytes,countStyle:.file)).fontWeight(.semibold)}}}.card();VStack(alignment:.leading,spacing:10){Label(language.text("Plan management","Gestion du forfait"),systemImage:"person.crop.circle.badge.checkmark").font(.headline);Text(language.text("Your Libérons plan determines the space available to protect your photos and videos.","Votre forfait Libérons détermine l’espace disponible pour protéger vos photos et vidéos.")).font(.subheadline).foregroundStyle(.secondary)}.card();Button{Task{await cloud.refresh()}}label:{Label(language.text("Refresh plan status","Actualiser l’état du forfait"),systemImage:"arrow.clockwise").frame(maxWidth:.infinity).frame(height:42)}.buttonStyle(.borderedProminent).disabled(cloud.isLoading)}.padding(20)}.background(LiberonsTheme.canvas).navigationTitle(language.text("Libérons plan","Forfait Libérons")).navigationBarTitleDisplayMode(.inline)}
    private var currentPlanName:String{guard cloud.quotaBytes>0 else{return language.text("Free · 2 GB","Gratuit · 2 Go")};if let plan=plans.min(by:{abs($0.bytes-cloud.quotaBytes)<abs($1.bytes-cloud.quotaBytes)}),isCurrent(plan.bytes){return plan.price=="Free" ? language.text("Free · 2 GB","Gratuit · 2 Go"):plan.name};return ByteCountFormatter.string(fromByteCount:cloud.quotaBytes,countStyle:.file)}
    private func isCurrent(_ bytes:Int64)->Bool{let tolerance=max(Int64(50_000_000),bytes/100);return abs(effectiveQuota-bytes)<=tolerance}
    private func localizedPrice(_ price:String)->String{if price=="Free"{return language.text("Free","Gratuit")};return language.language == .french ? price.replacingOccurrences(of:".",with:",").replacingOccurrences(of:"/month",with:" $/mois").replacingOccurrences(of:"$",with:"") : price}
}

